# RUN: llvm-mca -mtriple=aarch64 -mcpu=cortex-a78 -instruction-tables < %s | FileCheck %s

# Based on Cortex-A78 Software Optimization Guide
# s3.8 Miscellaneous data-processing instructions

# Address generation
adr      x0, #4
adrp     x0, #6553600

# Bitfield extract, one reg
#
# One reg form is when Rn==Rm or imm==0, all other forms
# are considered two regs.

extr     w0, w1, w1, #1
extr     w0, w1, w2, #0

# Bitfield extract, two regs
extr     w0, w1, w2, #1

# Bitfield move, basic
sbfm	w0, w1, #1, #15
sbfm	x0, x1, #1, #15

ubfm	w0, w1, #1, #15
ubfm	x0, x1, #1, #15

# Bitfield move, insert
bfm	w0, w1, #1, #15
bfm	x0, x1, #1, #15

# Count leading
cls	w0, w1
cls	x0, x1
clz	w0, w1
clz	x0, x1

# Move immed
movn     w0, #4
movn     x0, #4
movk     w0, #4
movk     x0, #4
movz     w0, #4
movz     x0, #4

# Reverse bits/bytes
rbit	w0, w1
rbit	x0, x1
rev	w0, w1
rev	x0, x1
rev16	w0, w1
rev16	x0, x1
rev32	x0, x1

# Variable shift
asr	w0, w1, w2
asr	x0, x1, x2
lsl	w0, w1, w2
lsl	x0, x1, x2
lsr	w0, w1, w2
lsr	x0, x1, x2
ror	w0, w1, w2
ror	x0, x1, x2

